655	/// Split raw bytes into records on LF (0x0a). The separator is not part of
656	/// any record. A trailing LF terminates the last record without adding an
657	/// empty one; an empty file yields zero records.
658	#[doc(hidden)]
659	pub fn split_records(data: &[u8]) -> Vec<&[u8]> {
660	    if data.is_empty() {
661	        return Vec::new();
662	    }
663	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
664	    if data.last() == Some(&b'\n') {
665	        records.pop();
666	    }
667	    records
668	}
