670	/// A fresh leaf hasher primed with the RFC 6962 section 2.1 leaf prefix 0x00.
671	fn new_leaf_hasher() -> Sha256 {
672	    let mut h = Sha256::new();
673	    h.update(&[0x00]);
674	    h
675	}
676	
677	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data). The prefix byte and
678	/// the record are fed to the hasher as two consecutive slices, so hashing a
679	/// record of any length needs no copy of the record and no allocation beyond
680	/// the hasher's fixed-size state.
681	fn leaf_hash(data: &[u8]) -> [u8; 32] {
682	    let mut h = new_leaf_hasher();
683	    h.update(data);
684	    h.finalize()
685	}
