696	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
697	/// that maintains the tree-construction rules: both `root` (via `mth`) and
698	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
699	/// two commands can never disagree on how a batch is shaped or hashed.
700	///
701	/// ```text
702	/// MTH([])      = SHA-256("")
703	/// MTH([d])     = SHA-256(0x00 || d)
704	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
705	/// ```
706	///
707	/// with k the largest power of two strictly smaller than n. Uneven batches
708	/// are handled by the recursion itself: no leaf is duplicated and no empty
709	/// record is appended to round the size up to a power of two.
710	///
711	/// `target` selects the one leaf a membership proof is built for:
712	///
713	/// ```text
714	/// PATH(m, [d0]) = []
715	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
716	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
717	/// ```
718	///
719	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
720	/// leaf `m` to the root are appended to `path` in leaf-to-root order
721	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
722	/// leaf into whichever subtree contains it, while the sibling subtree is
723	/// built with `None`. With `None` only the root is built. Every leaf hash and
724	/// every interior hash is computed exactly once in either mode, so producing
725	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
726	fn build_tree(
727	    leaves: &[&[u8]],
728	    target: Option<usize>,
729	    path: &mut Vec<[u8; 32]>,
730	) -> [u8; 32] {
731	    match leaves.len() {
732	        0 => sha256(&[]),
733	        1 => leaf_hash(leaves[0]),
734	        n => {
735	            // Largest power of two strictly smaller than n.
736	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
737	            let (left_leaves, right_leaves) = leaves.split_at(k);
738	            match target {
739	                // The audited leaf is in the left subtree; the right subtree
740	                // hash is this level's sibling on the leaf-to-root path.
741	                Some(m) if m < k => {
742	                    let left = build_tree(left_leaves, Some(m), path);
743	                    let right = build_tree(right_leaves, None, path);
744	                    path.push(right);
745	                    node_hash(&left, &right)
746	                }
747	                // The audited leaf is in the right subtree; reindex it
748	                // relative to that subtree and take the left subtree as the
749	                // sibling.
750	                Some(m) => {
751	                    let left = build_tree(left_leaves, None, path);
752	                    let right = build_tree(right_leaves, Some(m - k), path);
753	                    path.push(left);
754	                    node_hash(&left, &right)
755	                }
756	                // No audited leaf: both subtrees are plain root constructions.
757	                None => {
758	                    let left = build_tree(left_leaves, None, path);
759	                    let right = build_tree(right_leaves, None, path);
760	                    node_hash(&left, &right)
761	                }
762	            }
763	        }
764	    }
765	}
