788	// --- Streaming root computation ---------------------------------------------
789	//
790	// `roottrace root` must not hold the batch in memory: the file is read through
791	// a fixed-size buffer, every record is hashed as it streams past (a record is
792	// never stored, however long it is), and the only per-record state kept is
793	// the stack of completed subtree hashes below — at most one entry per bit of
794	// the record count, so O(log n) hashes independent of the file's byte length
795	// and of the longest record.
796	
797	/// Incremental RFC 6962 Merkle Tree Hash over an LF-separated byte stream.
798	///
799	/// Bytes are fed through [`RootStream::feed`] in chunks of any size; how many
800	/// bytes one read returns is meaningless to the result, and a record that
801	/// spans any number of chunks is hashed in full. Records are delimited by LF
802	/// exactly as [`split_records`] defines (the separator is not content, a
803	/// trailing LF only terminates the last record, an empty input is zero
804	/// records), and the tree is folded with the same largest-power-of-two split
805	/// as `build_tree`, so [`RootStream::finish`] returns exactly
806	/// `mth(&split_records(whole))` for the concatenation `whole` of everything
807	/// fed.
808	///
809	/// Memory use is a small fixed amount plus at most 64 subtree hashes (one per
810	/// bit of the record count): nothing grows with the number of bytes fed or
811	/// with the length of any single record.
812	#[doc(hidden)]
813	pub struct RootStream {
814	    /// Hasher for the record currently being accumulated, primed with 0x00.
815	    leaf: Sha256,
816	    /// Whether any content byte of the current record has been seen. A record
817	    /// only exists once it has content or is terminated by an LF, so an empty
818	    /// input is zero records and a trailing LF adds none.
819	    record_has_bytes: bool,
820	    /// Completed subtree hashes, bottom to top in strictly decreasing height;
821	    /// entry i covers 2^height consecutive leaves. Together the entries are
822	    /// the binary decomposition of the record count so far, which is exactly
823	    /// the shape the recursive largest-power-of-two split produces.
824	    subtrees: Vec<([u8; 32], u32)>,
825	}
826	
827	impl RootStream {
828	    #[doc(hidden)]
829	    pub fn new() -> Self {
830	        RootStream {
831	            leaf: new_leaf_hasher(),
832	            record_has_bytes: false,
833	            subtrees: Vec::new(),
834	        }
835	    }
836	
837	    /// Feed the next chunk of input. LF bytes split records and are not
838	    /// content; every other byte — space, tab, CR, NUL, non-UTF-8 — is hashed
839	    /// into the current record as-is.
840	    #[doc(hidden)]
841	    pub fn feed(&mut self, mut chunk: &[u8]) {
842	        while let Some(pos) = chunk.iter().position(|&b| b == b'\n') {
843	            self.leaf.update(&chunk[..pos]);
844	            self.record_has_bytes |= pos > 0;
845	            self.finish_record();
846	            chunk = &chunk[pos + 1..];
847	        }
848	        self.leaf.update(chunk);
849	        self.record_has_bytes |= !chunk.is_empty();
850	    }
851	
852	    /// Close the current record: finalize its leaf hash and fold it into the
853	    /// subtree stack, merging completed subtrees of equal height so the stack
854	    /// always holds the largest complete subtrees on the left.
855	    fn finish_record(&mut self) {
856	        let leaf = std::mem::replace(&mut self.leaf, new_leaf_hasher()).finalize();
857	        self.record_has_bytes = false;
858	        let mut acc = leaf;
859	        let mut height = 0u32;
860	        while self.subtrees.last().is_some_and(|&(_, h)| h == height) {
861	            let (left, _) = self.subtrees.pop().unwrap();
862	            acc = node_hash(&left, &acc);
863	            height += 1;
864	        }
865	        self.subtrees.push((acc, height));
866	    }
867	
868	    /// Produce the batch root. A final record without a terminating LF counts
869	    /// in full; a trailing LF adds no record; no input at all is the RFC 6962
870	    /// empty-tree hash SHA-256("").
871	    #[doc(hidden)]
872	    pub fn finish(mut self) -> [u8; 32] {
873	        if self.record_has_bytes {
874	            self.finish_record();
875	        }
876	        match self.subtrees.pop() {
877	            None => sha256(&[]),
878	            Some((mut acc, _)) => {
879	                // Fold the remaining complete subtrees right to left: reading
880	                // the binary decomposition of the record count this way is
881	                // the recursive k-split of build_tree.
882	                while let Some((left, _)) = self.subtrees.pop() {
883	                    acc = node_hash(&left, &acc);
884	                }
885	                acc
886	            }
887	        }
888	    }
889	}
