977	/// Streaming SHA-256 (FIPS 180-4). The working state is the eight hash words
978	/// plus one 64-byte block buffer, so the temporary memory a hash needs is a
979	/// small constant no matter how long the hashed input is: a record is fed in
980	/// place from the batch buffer and is never copied for hashing.
981	struct Sha256 {
982	    h: [u32; 8],
983	    buf: [u8; 64],
984	    buf_len: usize,
985	    total_len: u64,
986	}
987	
988	impl Sha256 {
989	    fn new() -> Self {
990	        #[cfg(test)]
991	        SHA256_CALLS.with(|c| c.set(c.get() + 1));
992	        Sha256 {
993	            h: [
994	                0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
995	                0x1f83d9ab, 0x5be0cd19,
996	            ],
997	            buf: [0u8; 64],
998	            buf_len: 0,
999	            total_len: 0,
1000	        }
1001	    }
1002	
1003	    /// Feed the next chunk of input. Bytes are consumed straight from `data`;
1004	    /// only a partial trailing block is ever staged in `buf`.
1005	    fn update(&mut self, mut data: &[u8]) {
1006	        self.total_len = self.total_len.wrapping_add(data.len() as u64);
1007	        if self.buf_len > 0 {
1008	            let take = (64 - self.buf_len).min(data.len());
1009	            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
1010	            self.buf_len += take;
1011	            data = &data[take..];
1012	            if self.buf_len == 64 {
1013	                let block = self.buf;
1014	                self.compress(&block);
1015	                self.buf_len = 0;
1016	            }
1017	        }
1018	        while data.len() >= 64 {
1019	            let (block, rest) = data.split_at(64);
1020	            let mut staged = [0u8; 64];
1021	            staged.copy_from_slice(block);
1022	            self.compress(&staged);
1023	            data = rest;
1024	        }
1025	        if !data.is_empty() {
1026	            self.buf[..data.len()].copy_from_slice(data);
1027	            self.buf_len = data.len();
1028	        }
1029	    }
1030	
1031	    /// Append the FIPS 180-4 padding (0x80, zeros, 64-bit big-endian bit
1032	    /// length) inside the block buffer and produce the digest. At most one
1033	    /// extra block is needed when the length field does not fit after the
1034	    /// final data byte.
1035	    fn finalize(mut self) -> [u8; 32] {
1036	        let bit_len = self.total_len.wrapping_mul(8);
1037	        self.update(&[0x80]);
1038	        while self.buf_len != 56 {
1039	            self.update(&[0]);
1040	        }
1041	        self.update(&bit_len.to_be_bytes());
1042	        debug_assert_eq!(self.buf_len, 0, "padding must end on a block boundary");
1043	
1044	        let mut out = [0u8; 32];
1045	        for (i, word) in self.h.iter().enumerate() {
1046	            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
1047	        }
1048	        out
1049	    }
