1051	    /// The SHA-256 compression function over one 64-byte block.
1052	    fn compress(&mut self, block: &[u8; 64]) {
1053	        let mut w = [0u32; 64];
1054	        for (i, word) in block.chunks_exact(4).enumerate() {
1055	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
1056	        }
1057	        for i in 16..64 {
1058	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
1059	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
1060	            w[i] = w[i - 16]
1061	                .wrapping_add(s0)
1062	                .wrapping_add(w[i - 7])
1063	                .wrapping_add(s1);
1064	        }
1065	
1066	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = self.h;
1067	        for i in 0..64 {
1068	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
1069	            let ch = (e & f) ^ ((!e) & g);
1070	            let t1 = hh
1071	                .wrapping_add(s1)
1072	                .wrapping_add(ch)
1073	                .wrapping_add(K[i])
1074	                .wrapping_add(w[i]);
1075	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
1076	            let maj = (a & b) ^ (a & c) ^ (b & c);
1077	            let t2 = s0.wrapping_add(maj);
1078	            hh = g;
1079	            g = f;
1080	            f = e;
1081	            e = d.wrapping_add(t1);
1082	            d = c;
1083	            c = b;
1084	            b = a;
1085	            a = t1.wrapping_add(t2);
1086	        }
1087	
1088	        self.h[0] = self.h[0].wrapping_add(a);
1089	        self.h[1] = self.h[1].wrapping_add(b);
1090	        self.h[2] = self.h[2].wrapping_add(c);
1091	        self.h[3] = self.h[3].wrapping_add(d);
1092	        self.h[4] = self.h[4].wrapping_add(e);
1093	        self.h[5] = self.h[5].wrapping_add(f);
1094	        self.h[6] = self.h[6].wrapping_add(g);
1095	        self.h[7] = self.h[7].wrapping_add(hh);
1096	    }
1097	}
