1248	    /// Root of a batch computed by streaming it through `chunk`-byte feeds.
1249	    fn streaming_root(data: &[u8], chunk: usize) -> [u8; 32] {
1250	        let mut s = RootStream::new();
1251	        for piece in data.chunks(chunk) {
1252	            s.feed(piece);
1253	        }
1254	        s.finish()
