1967	        // A synthetic proof for a tree of 2^63 records at index 2^32: the
1968	        // audit path element i is the 64-char lowercase hex of i, and the
1969	        // trusted root is recomputed here with the internal verifier. The
1970	        // point is that u64 sizes/indices flow through verify_membership
1971	        // untruncated and come back in the Membership result unchanged.
1972	        let record = b"big-tree-record\x00\xff\xfe";
1973	        let size: u64 = 1 << 63;
1974	        let index: u64 = 1 << 32;
1975	        let path: Vec<[u8; 32]> = (0..63u64)
1976	            .map(|i| {
1977	                let s = format!("{i:064x}");
1978	                let mut h = [0u8; 32];
1979	                for (j, pair) in s.as_bytes().chunks_exact(2).enumerate() {
1980	                    h[j] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
1981	                }
1982	                h
1983	            })
1984	            .collect();
1985	        let root = include_record(leaf_hash(record), index, size, &path).unwrap();
1986	        let proof = proof_json(size, index, &root, &path).into_bytes();
