/// Sink adapter that folds the splitter's record events into the Merkle
/// subtree stack: content bytes go straight into the current leaf hasher and
/// each completed record folds its leaf hash into the completed subtrees.
struct TreeSink<'a> {
    leaf: &'a mut Sha256,
    subtrees: &'a mut Vec<([u8; 32], u32)>,
}

impl TreeSink<'_> {
    fn handle(&mut self, event: RecordEvent<'_>) {
        match event {
            RecordEvent::RecordBytes(bytes) => self.leaf.update(bytes),
            RecordEvent::RecordEnd => {
